ALTER TABLE "public"."campi"
  DROP CONSTRAINT "campi_universidade_id_fkey";

ALTER TABLE "public"."curso"
  DROP CONSTRAINT "curso_camp_id_fkey";

ALTER TABLE "public"."perfil"
  DROP CONSTRAINT "aluno_campi_id_fkey";

ALTER TABLE "public"."curso"
  DROP COLUMN "camp_id";

ALTER TABLE "public"."perfil"
  DROP COLUMN "campi_id";

DROP TABLE "public"."campi";

DROP TABLE "public"."universidade";

CREATE TABLE "public"."instituicao" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."universidade_id_seq") NOT NULL,
  "criado_em"    timestamp with time zone NOT NULL DEFAULT now(),
  "nome"         character varying,
  "sigla"        character varying,
  "logo_url"     text,
  "banner_url"   text,
  "site_oficial" character varying,
  CONSTRAINT "universidade_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."instituicao"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."unidade" (
  "id"             bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."campi_id_seq") NOT NULL,
  "criado_em"      timestamp with time zone NOT NULL DEFAULT now(),
  "instituicao_id" bigint                   NOT NULL,
  "nome"           character varying,
  "cidade"         character varying,
  "estado"         character varying,
  "endereco"       text,
  "logo_url"       text,
  CONSTRAINT "campi_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."unidade"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."curso"
  ADD COLUMN "unidade_id" bigint NOT NULL;

ALTER TABLE "public"."perfil"
  ADD COLUMN "unidade_id" bigint NOT NULL;

ALTER TABLE "public"."curso"
  ADD CONSTRAINT "curso_unidade_id_fkey" FOREIGN KEY (unidade_id) REFERENCES public.unidade(id);

ALTER TABLE "public"."perfil"
  ADD CONSTRAINT "perfil_unidade_id_fkey" FOREIGN KEY (unidade_id) REFERENCES public.unidade(id) ON UPDATE RESTRICT ON DELETE RESTRICT;

ALTER TABLE "public"."unidade"
  ADD CONSTRAINT "unidade_instituicao_id_fkey" FOREIGN KEY (instituicao_id) REFERENCES public.instituicao(id) ON UPDATE RESTRICT ON DELETE RESTRICT;

COMMENT ON TABLE "public"."curso" IS 'Curso de uma instituição';

COMMENT ON TABLE "public"."instituicao" IS 'Faculdade ou instituição';

COMMENT ON TABLE "public"."unidade" IS 'Unidade ou campus dentro da faculdade/instituição';

